export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.enabled = true;
    this.noise = null;
    this.started = false;
  }

  init() {
    if (this.ctx) { this.resume(); return; }
    const Ctx = window.AudioContext || window.webkitAudioContext;
    if (!Ctx) return;
    this.ctx = new Ctx();
    this.master = this.ctx.createGain();
    this.master.gain.value = this.enabled ? 0.62 : 0;
    const comp = this.ctx.createDynamicsCompressor();
    comp.threshold.value = -18;
    comp.knee.value = 18;
    comp.ratio.value = 5;
    comp.attack.value = 0.003;
    comp.release.value = 0.22;
    this.master.connect(comp).connect(this.ctx.destination);

    // pre-baked noise buffer
    const len = this.ctx.sampleRate * 2;
    this.noise = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const data = this.noise.getChannelData(0);
    for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1;

    this.startAmbient();
    this.started = true;
  }

  resume() {
    if (this.ctx && this.ctx.state === 'suspended') this.ctx.resume().catch(() => {});
  }

  setEnabled(on) {
    this.enabled = on;
    if (this.master) this.master.gain.setTargetAtTime(on ? 0.62 : 0, this.ctx.currentTime, 0.05);
  }

  get t() { return this.ctx ? this.ctx.currentTime : 0; }

  startAmbient() {
    const ctx = this.ctx;
    const src = ctx.createBufferSource();
    src.buffer = this.noise; src.loop = true;
    const lp = ctx.createBiquadFilter(); lp.type = 'lowpass'; lp.frequency.value = 320; lp.Q.value = 0.6;
    const g = ctx.createGain(); g.gain.value = 0.045;
    // slow wind swell
    const lfo = ctx.createOscillator(); lfo.frequency.value = 0.06;
    const lfoG = ctx.createGain(); lfoG.gain.value = 0.02;
    lfo.connect(lfoG).connect(g.gain);
    lfo.start();
    src.connect(lp).connect(g).connect(this.master);
    src.start();

    // low industrial drone
    for (const [freq, vol] of [[48, 0.014], [73.4, 0.008], [110, 0.0035]]) {
      const o = ctx.createOscillator(); o.type = 'sine'; o.frequency.value = freq;
      const og = ctx.createGain(); og.gain.value = vol;
      const detune = ctx.createOscillator(); detune.frequency.value = 0.07;
      const dg = ctx.createGain(); dg.gain.value = freq * 0.004;
      detune.connect(dg).connect(o.detune); detune.start();
      o.connect(og).connect(this.master); o.start();
    }
  }

  _noiseBurst({ dur = 0.2, gain = 0.5, type = 'bandpass', freq = 900, q = 0.8, sweep = 0, attack = 0.002, lowpass = 0 }) {
    if (!this.ctx) return;
    const ctx = this.ctx, t = ctx.currentTime;
    const src = ctx.createBufferSource(); src.buffer = this.noise;
    src.playbackRate.value = 0.9 + Math.random() * 0.25;
    const filter = ctx.createBiquadFilter(); filter.type = type; filter.frequency.value = freq; filter.Q.value = q;
    if (sweep) filter.frequency.exponentialRampToValueAtTime(Math.max(60, freq + sweep), t + dur);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(gain, t + attack);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    let node = src.connect(filter);
    if (lowpass) {
      const lp = ctx.createBiquadFilter(); lp.type = 'lowpass'; lp.frequency.value = lowpass;
      node = node.connect(lp);
    }
    node.connect(g).connect(this.master);
    src.start(t, Math.random() * 1.2);
    src.stop(t + dur + 0.05);
  }

  _thump({ start = 120, end = 42, dur = 0.18, gain = 0.5, type = 'sine', delay = 0 }) {
    if (!this.ctx) return;
    const ctx = this.ctx, t = ctx.currentTime + delay;
    const o = ctx.createOscillator(); o.type = type;
    o.frequency.setValueAtTime(start, t);
    o.frequency.exponentialRampToValueAtTime(end, t + dur);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(gain, t + 0.005);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    o.connect(g).connect(this.master);
    o.start(t); o.stop(t + dur + 0.03);
  }

  shot() {
    if (!this.ctx) return;
    this._noiseBurst({ dur: 0.16, gain: 0.62, freq: 1500, q: 0.55, sweep: -1150 });
    this._noiseBurst({ dur: 0.055, gain: 0.38, freq: 3400, q: 1.2 });
    this._thump({ start: 135, end: 38, dur: 0.15, gain: 0.5 });
    this._thump({ start: 78, end: 30, dur: 0.22, gain: 0.32, delay: 0.01 });
    // mechanical click
    this._noiseBurst({ dur: 0.03, gain: 0.09, freq: 4400, q: 2.4 });
  }

  enemyShot(distance = 20) {
    const v = Math.max(0.06, Math.min(0.42, 14 / Math.max(6, distance)));
    this._noiseBurst({ dur: 0.15, gain: v, freq: 720, q: 0.7, sweep: -460, lowpass: 2400 });
    this._thump({ start: 95, end: 38, dur: 0.13, gain: v * 0.6 });
  }

  dry() {
    this._noiseBurst({ dur: 0.035, gain: 0.18, freq: 2600, q: 2.4 });
  }

  reloadStart() {
    this._noiseBurst({ dur: 0.07, gain: 0.14, freq: 900, q: 1.4 });
    setTimeout(() => { this._noiseBurst({ dur: 0.09, gain: 0.2, freq: 600, q: 1.1 }); }, 380);
    setTimeout(() => { this._thump({ start: 220, end: 90, dur: 0.06, gain: 0.16 }); }, 760);
  }

  reloadEnd() {
    this._noiseBurst({ dur: 0.05, gain: 0.24, freq: 1800, q: 2.2 });
    this._thump({ start: 260, end: 110, dur: 0.07, gain: 0.2 });
    setTimeout(() => this._noiseBurst({ dur: 0.06, gain: 0.2, freq: 1200, q: 1.8 }), 90);
  }

  hit(headshot = false) {
    this._thump({ start: headshot ? 1750 : 1250, end: headshot ? 800 : 620, dur: 0.055, gain: 0.14, type: 'triangle' });
    this._noiseBurst({ dur: 0.035, gain: 0.07, freq: 3200, q: 2 });
  }

  kill() {
    this._thump({ start: 300, end: 80, dur: 0.18, gain: 0.18, type: 'triangle' });
  }

  footstep(running = false) {
    this._noiseBurst({ dur: 0.09, gain: running ? 0.11 : 0.07, freq: 380, q: 0.8, lowpass: 900 });
  }

  hurt() {
    this._thump({ start: 90, end: 42, dur: 0.3, gain: 0.35 });
    this._noiseBurst({ dur: 0.14, gain: 0.18, freq: 380, q: 0.8 });
  }

  explosion() {
    this._noiseBurst({ dur: 1.1, gain: 0.75, freq: 900, q: 0.5, sweep: -700, lowpass: 1800 });
    this._thump({ start: 70, end: 18, dur: 0.95, gain: 0.7 });
    this._noiseBurst({ dur: 0.25, gain: 0.4, freq: 2600, q: 0.7 });
  }

  wave() {
    if (!this.ctx) return;
    const ctx = this.ctx, t = ctx.currentTime;
    for (const [delay, base] of [[0, 340], [0.34, 435]]) {
      const o = ctx.createOscillator(); o.type = 'sawtooth';
      o.frequency.setValueAtTime(base, t + delay);
      o.frequency.exponentialRampToValueAtTime(base * 1.5, t + delay + 0.5);
      const g = ctx.createGain();
      g.gain.setValueAtTime(0.0001, t + delay);
      g.gain.exponentialRampToValueAtTime(0.045, t + delay + 0.05);
      g.gain.exponentialRampToValueAtTime(0.0001, t + delay + 0.8);
      const lp = ctx.createBiquadFilter(); lp.type = 'lowpass'; lp.frequency.value = 1400;
      o.connect(lp).connect(g).connect(this.master);
      o.start(t + delay); o.stop(t + delay + 0.9);
    }
  }

  pickup() {
    this._thump({ start: 620, end: 900, dur: 0.1, gain: 0.1, type: 'triangle' });
  }

  ui() {
    this._noiseBurst({ dur: 0.03, gain: 0.05, freq: 2000, q: 2 });
  }
}

const $ = (id) => document.getElementById(id);

const DIRS = ['N', 'NE', 'E', 'SE', 'S', 'SW', 'W', 'NW'];

export const ui = {
  el: {},
  prevScreen: 'menu',
  bannerTimer: 0,
  damageTimer: 0,

  init() {
    const el = this.el;
    for (const id of [
      'hud', 'screen-menu', 'screen-briefing', 'screen-settings', 'screen-pause', 'screen-over',
      'hud-wave', 'hud-remaining', 'hud-score', 'hud-health', 'hud-health-state', 'health-fill',
      'hud-ammo', 'hud-reserve', 'hud-grenades', 'hud-weapon', 'compass-heading', 'compass-ticks',
      'killfeed', 'banner', 'banner-title', 'banner-sub', 'banner-kicker', 'hitmarker', 'crosshair',
      'reload-hint', 'reload-fill', 'radar', 'damage-arrow', 'pause-wave', 'pause-score',
      'over-wave', 'over-kills', 'over-acc', 'over-score', 'over-flavour', 'loader', 'loader-fill',
    ]) el[id] = $(id);
    el.compassTicks = document.querySelector('.compass-ticks');
    el.bannerKicker = document.querySelector('.banner-kicker');

    // dynamic damage flash layer
    this.flash = document.createElement('div');
    this.flash.id = 'damage-flash';
    document.body.appendChild(this.flash);

    this.radarCtx = el.radar.getContext('2d');
    this.radarSweep = 0;
    this.lastCompass = 999;
  },

  setMobile(touch) { document.body.classList.toggle('touch', !!touch); },

  hideAllScreens() {
    for (const id of ['screen-menu', 'screen-briefing', 'screen-settings', 'screen-pause', 'screen-over']) {
      this.el[id].classList.add('hidden');
    }
  },

  showMenu() {
    this.hideAllScreens();
    this.el['screen-menu'].classList.remove('hidden');
    this.el.hud.classList.add('hidden');
    document.body.classList.remove('low-health', 'hit');
    this.el['damage-arrow'].style.opacity = '0';
    this.el['killfeed'].innerHTML = '';
    this.el.banner.classList.remove('show');
  },

  showHUD() {
    this.hideAllScreens();
    this.el.hud.classList.remove('hidden');
  },

  showPause(wave, score) {
    this.el['pause-wave'].textContent = String(wave).padStart(2, '0');
    this.el['pause-score'].textContent = String(score);
    this.hideAllScreens();
    this.el['screen-pause'].classList.remove('hidden');
  },

  showBriefing() {
    this.prevScreen = this.el['screen-menu'].classList.contains('hidden') ? 'pause' : 'menu';
    this.hideAllScreens();
    this.el['screen-briefing'].classList.remove('hidden');
  },

  closeBriefing() {
    this.hideAllScreens();
    this.el[`screen-${this.prevScreen}`].classList.remove('hidden');
  },

  showSettings() {
    this.prevScreen = this.el['screen-menu'].classList.contains('hidden') ? 'pause' : 'menu';
    this.hideAllScreens();
    this.el['screen-settings'].classList.remove('hidden');
  },

  closeSettings() {
    this.hideAllScreens();
    this.el[`screen-${this.prevScreen}`].classList.remove('hidden');
  },

  showGameOver(stats) {
    this.hideAllScreens();
    this.el['over-wave'].textContent = stats.waves;
    this.el['over-kills'].textContent = stats.kills;
    this.el['over-acc'].textContent = `${stats.accuracy}%`;
    this.el['over-score'].textContent = String(stats.score);
    const lines = [
      'The perimeter has fallen. Regroup and try again.',
      'Extraction was not secured. The zone belongs to them now.',
      'You held the line. It was not enough. Not yet.',
    ];
    this.el['over-flavour'].textContent = lines[stats.waves % lines.length];
    this.el['screen-over'].classList.remove('hidden');
    this.el.hud.classList.add('hidden');
  },

  loader(progress) {
    if (this.el['loader-fill']) this.el['loader-fill'].style.width = `${Math.round(progress * 100)}%`;
  },
  hideLoader() { this.el.loader?.classList.add('done'); },

  updateHUD(s) {
    const el = this.el;
    el['hud-health'].textContent = Math.max(0, Math.ceil(s.health));
    el['health-fill'].style.width = `${Math.max(0, Math.min(100, s.health))}%`;
    el['hud-ammo'].textContent = String(s.ammo).padStart(2, '0');
    el['hud-reserve'].textContent = String(s.reserve);
    el['hud-grenades'].textContent = s.grenades;
    el['hud-wave'].textContent = `WAVE ${String(s.wave).padStart(2, '0')}`;
    el['hud-remaining'].textContent = `HOSTILES ${String(s.remaining).padStart(2, '0')}`;
    el['hud-score'].textContent = String(s.score).padStart(6, '0');
    const state = s.health > 65 ? 'STABLE' : s.health > 30 ? 'WOUNDED' : 'CRITICAL';
    el['hud-health-state'].textContent = state;
    document.body.classList.toggle('low-health', s.health <= 30 && s.health > 0);
    el['reload-hint'].classList.toggle('show', !!s.reloading);
    el['reload-fill'].style.width = `${Math.round((s.reloadProgress || 0) * 100)}%`;
    el['hud-ammo'].style.color = s.ammo === 0 ? '#ff6459' : s.ammo <= 6 ? '#ffbd6e' : '';
    if (s.ammo === 0) el['hud-ammo'].style.textShadow = '0 0 18px rgba(255,70,60,0.45)';
    else el['hud-ammo'].style.textShadow = '';
  },

  setCrosshair(spreadPx, ads) {
    this.el.crosshair.style.setProperty('--spread', `${spreadPx.toFixed(1)}px`);
    this.el.crosshair.classList.toggle('ads', !!ads);
  },

  hitmarker(kill) {
    const h = this.el.hitmarker;
    h.classList.remove('show', 'kill');
    void h.offsetWidth;
    if (kill) h.classList.add('kill');
    h.classList.add('show');
  },

  killfeed(headshot) {
    const item = document.createElement('div');
    item.className = 'feed-item' + (headshot ? ' head' : '');
    item.innerHTML = headshot ? '<b>CRITICAL</b> HOSTILE NEUTRALIZED' : 'HOSTILE NEUTRALIZED';
    this.el['killfeed'].prepend(item);
    while (this.el['killfeed'].children.length > 5) this.el['killfeed'].lastChild.remove();
    setTimeout(() => item.remove(), 3200);
  },

  banner(kicker, title, sub, duration = 2400) {
    const { banner } = this.el;
    this.el.bannerKicker.textContent = kicker;
    this.el['banner-title'].textContent = title;
    this.el['banner-sub'].textContent = sub;
    banner.classList.remove('show');
    void banner.offsetWidth;
    banner.classList.add('show');
    clearTimeout(this.bannerTimer);
    this.bannerTimer = setTimeout(() => banner.classList.remove('show'), duration);
  },

  damage(angleDeg) {
    const a = this.el['damage-arrow'];
    a.style.transition = 'none';
    a.style.transform = `rotate(${angleDeg}deg)`;
    a.style.opacity = '0.95';
    this.flash.style.transition = 'none';
    this.flash.style.opacity = '0.48';
    clearTimeout(this.damageTimer);
    this.damageTimer = setTimeout(() => {
      a.style.transition = 'opacity 0.55s ease';
      a.style.opacity = '0';
      this.flash.style.transition = 'opacity 0.5s ease';
      this.flash.style.opacity = '0';
    }, 90);
  },

  updateCompass(yaw) {
    const heading = ((-yaw * 180 / Math.PI) % 360 + 360) % 360;
    if (Math.abs(heading - this.lastCompass) < 0.25) return;
    this.lastCompass = heading;
    const idx = Math.round(heading / 45) % 8;
    this.el['compass-heading'].textContent = `${DIRS[idx]}  ${String(Math.round(heading)).padStart(3, '0')}`;
    this.el.compassTicks.style.backgroundPositionX = `${-heading * 2.4}px`;
  },

  radar(enemies, pos, yaw, dt) {
    const ctx = this.radarCtx;
    const w = 168, c = w / 2, R = 80;
    this.radarSweep += dt * 1.6;
    ctx.clearRect(0, 0, w, w);
    ctx.save();
    ctx.beginPath(); ctx.arc(c, c, R, 0, Math.PI * 2); ctx.clip();
    ctx.fillStyle = 'rgba(4, 10, 13, 0.52)'; ctx.fillRect(0, 0, w, w);
    // rings
    ctx.strokeStyle = 'rgba(120, 220, 240, 0.13)'; ctx.lineWidth = 1;
    for (const r of [27, 54, 80]) { ctx.beginPath(); ctx.arc(c, c, r, 0, Math.PI * 2); ctx.stroke(); }
    ctx.beginPath(); ctx.moveTo(c, 0); ctx.lineTo(c, w); ctx.moveTo(0, c); ctx.lineTo(w, c); ctx.stroke();
    // sweep
    const g = ctx.createConicGradient ? ctx.createConicGradient(this.radarSweep, c, c) : null;
    if (g) {
      g.addColorStop(0, 'rgba(130, 240, 255, 0.18)');
      g.addColorStop(0.12, 'rgba(130, 240, 255, 0.02)');
      g.addColorStop(1, 'rgba(130, 240, 255, 0)');
      ctx.fillStyle = g; ctx.beginPath(); ctx.arc(c, c, R, 0, Math.PI * 2); ctx.fill();
    }
    const cos = Math.cos(yaw), sin = Math.sin(yaw);
    const scale = 2.35;
    for (const e of enemies) {
      if (!e.alive) continue;
      const dx = e.position.x - pos.x, dz = e.position.z - pos.z;
      const rx = dx * cos - dz * sin;
      const ry = dx * sin + dz * cos;
      const d = Math.hypot(rx, ry);
      if (d * scale > R - 3) continue;
      const x = c + rx * scale, y = c + ry * scale;
      ctx.fillStyle = '#ff5a46';
      ctx.shadowColor = '#ff3a20'; ctx.shadowBlur = 7;
      ctx.beginPath(); ctx.arc(x, y, 2.6, 0, Math.PI * 2); ctx.fill();
      ctx.shadowBlur = 0;
    }
    // player
    ctx.fillStyle = '#ffd58c'; ctx.shadowColor = '#f0a02a'; ctx.shadowBlur = 8;
    ctx.beginPath(); ctx.moveTo(c, c - 5.5); ctx.lineTo(c + 4, c + 4); ctx.lineTo(c, c + 2.2); ctx.lineTo(c - 4, c + 4); ctx.closePath(); ctx.fill();
    ctx.shadowBlur = 0;
    ctx.restore();
  },
};

import * as THREE from 'three';
import { createEnemyRifle } from './weapons.js';

const _v1 = new THREE.Vector3();
const _v2 = new THREE.Vector3();

function box(w, h, d, mat, x = 0, y = 0, z = 0) {
  const m = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat);
  m.position.set(x, y, z);
  m.castShadow = true; m.receiveShadow = true;
  return m;
}

function createSoldier(hitMeshes, tier) {
  const uniform = new THREE.MeshStandardMaterial({ color: tier > 2 ? 0x2c3138 : 0x353b31, roughness: 0.9, metalness: 0.04 });
  const uniform2 = new THREE.MeshStandardMaterial({ color: 0x272b26, roughness: 0.92 });
  const vest = new THREE.MeshStandardMaterial({ color: 0x171a18, roughness: 0.78, metalness: 0.12 });
  const helmetMat = new THREE.MeshStandardMaterial({ color: 0x252a26, roughness: 0.72, metalness: 0.15 });
  const skin = new THREE.MeshStandardMaterial({ color: 0x8c5d3f, roughness: 0.86 });
  const rubber = new THREE.MeshStandardMaterial({ color: 0x121312, roughness: 0.95 });
  const visorMat = new THREE.MeshStandardMaterial({
    color: 0x330b05, emissive: 0xff3418, emissiveIntensity: 2.4, roughness: 0.25, metalness: 0.4,
  });
  const patch = new THREE.MeshStandardMaterial({ color: 0x8a3c27, roughness: 0.8 });

  const root = new THREE.Group();
  const model = new THREE.Group();
  root.add(model);

  const tag = (mesh, mult) => {
    mesh.userData.hitMult = mult;
    hitMeshes.push(mesh);
    return mesh;
  };

  // legs
  const legs = [];
  for (const side of [-1, 1]) {
    const hip = new THREE.Group();
    hip.position.set(side * 0.13, 0.96, 0);
    const thigh = box(0.175, 0.44, 0.19, uniform, 0, -0.21, 0);
    tag(thigh, 0.72);
    hip.add(thigh);
    const kneePad = box(0.16, 0.12, 0.055, vest, 0, -0.4, -0.11);
    hip.add(kneePad);
    const shin = new THREE.Group();
    shin.position.set(0, -0.42, 0);
    const calf = box(0.15, 0.4, 0.165, uniform, 0, -0.2, 0);
    tag(calf, 0.72);
    shin.add(calf);
    const boot = box(0.16, 0.15, 0.27, rubber, 0, -0.42, -0.035);
    tag(boot, 0.72);
    shin.add(boot);
    hip.add(shin);
    model.add(hip);
    legs.push({ hip, shin, phase: side > 0 ? 0 : Math.PI });
  }

  // pelvis + belt
  const pelvis = box(0.42, 0.24, 0.26, uniform2, 0, 0.98, 0);
  tag(pelvis, 1);
  model.add(pelvis);
  model.add(box(0.45, 0.09, 0.29, vest, 0, 1.08, 0));
  for (let i = -1; i <= 1; i++) model.add(box(0.1, 0.11, 0.05, uniform2, i * 0.14, 1.0, -0.15));

  // torso
  const torso = box(0.5, 0.55, 0.28, uniform, 0, 1.35, 0);
  tag(torso, 1);
  model.add(torso);
  // plate carrier
  const carrier = box(0.55, 0.4, 0.34, vest, 0, 1.37, 0);
  tag(carrier, 1);
  model.add(carrier);
  // pouches
  for (let i = -1; i <= 1; i++) {
    model.add(box(0.13, 0.15, 0.08, uniform2, i * 0.15, 1.24, -0.19));
  }
  // shoulder pads
  for (const side of [-1, 1]) {
    const pad = box(0.17, 0.13, 0.28, vest, side * 0.31, 1.55, 0);
    pad.rotation.z = side * -0.2;
    model.add(pad);
  }
  // backpack
  model.add(box(0.36, 0.38, 0.17, vest, 0, 1.38, 0.19));
  model.add(box(0.1, 0.2, 0.06, patch, 0.08, 1.55, 0.28));

  // arms
  const arms = [];
  for (const side of [-1, 1]) {
    const shoulder = new THREE.Group();
    shoulder.position.set(side * 0.35, 1.53, 0);
    const upper = box(0.14, 0.36, 0.16, uniform, 0, -0.17, 0);
    tag(upper, 0.7);
    shoulder.add(upper);
    const elbow = new THREE.Group();
    elbow.position.set(0, -0.35, 0);
    const fore = box(0.125, 0.34, 0.14, uniform2, 0, -0.16, 0);
    tag(fore, 0.7);
    elbow.add(fore);
    const glove = box(0.13, 0.13, 0.17, rubber, 0, -0.35, -0.02);
    tag(glove, 0.7);
    elbow.add(glove);
    shoulder.add(elbow);
    model.add(shoulder);
    arms.push({ shoulder, elbow, side });
  }
  // pose arms toward rifle
  const right = arms.find(a => a.side > 0);
  const left = arms.find(a => a.side < 0);
  right.shoulder.rotation.set(-1.12, 0, -0.18);
  right.elbow.rotation.set(-0.5, 0.12, 0);
  left.shoulder.rotation.set(-1.32, 0, 0.55);
  left.elbow.rotation.set(-0.35, -0.1, 0);

  // head
  const neck = box(0.15, 0.12, 0.15, skin, 0, 1.66, 0);
  tag(neck, 2);
  model.add(neck);
  const head = new THREE.Mesh(new THREE.SphereGeometry(0.155, 12, 10), skin);
  head.position.set(0, 1.77, 0); head.scale.set(0.95, 1.05, 0.95);
  head.castShadow = true;
  tag(head, 3);
  model.add(head);
  // helmet dome
  const helmet = new THREE.Mesh(new THREE.SphereGeometry(0.19, 14, 10, 0, Math.PI * 2, 0, Math.PI * 0.62), helmetMat);
  helmet.position.set(0, 1.79, 0); helmet.scale.set(1, 0.9, 1.04);
  helmet.castShadow = true;
  tag(helmet, 3);
  model.add(helmet);
  // helmet rim + side rails
  model.add(box(0.36, 0.05, 0.3, helmetMat, 0, 1.75, 0.01));
  for (const side of [-1, 1]) model.add(box(0.035, 0.06, 0.17, helmetMat, side * 0.18, 1.8, 0));
  // visor / night optics
  const visor = box(0.24, 0.065, 0.06, visorMat, 0, 1.77, -0.145);
  model.add(visor);
  const optic = box(0.07, 0.07, 0.13, vest, 0, 1.73, -0.2);
  model.add(optic);
  const opticLens = box(0.055, 0.055, 0.015, visorMat, 0, 1.73, -0.268);
  model.add(opticLens);
  // jaw mask
  model.add(box(0.19, 0.1, 0.05, rubber, 0, 1.68, -0.13));

  // rifle
  const rifle = createEnemyRifle();
  rifle.group.position.set(0.17, 1.33, -0.3);
  rifle.group.rotation.y = 0.03;
  model.add(rifle.group);
  const muzzle = rifle.muzzle;
  const flash = rifle.flash;

  model.scale.setScalar(1.0);

  // underglow unit marker (subtle)
  const marker = new THREE.Mesh(
    new THREE.RingGeometry(0.2, 0.26, 16),
    new THREE.MeshBasicMaterial({ color: 0xff2e18, transparent: true, opacity: 0.22, side: THREE.DoubleSide, depthWrite: false })
  );
  marker.rotation.x = -Math.PI / 2;
  marker.position.y = 0.025;
  root.add(marker);

  return { root, model, legs, arms, muzzle, flash, marker, visorMat };
}

export class Enemy {
  constructor(game, pos, tier = 1) {
    this.game = game;
    this.position = pos.clone();
    this.position.y = 0;
    this.tier = tier;
    this.maxHealth = 95 + tier * 14;
    this.health = this.maxHealth;
    this.alive = true;
    this.deadT = 0;
    this.removed = false;
    this.spawnDelay = 0.75;
    this.walkPhase = Math.random() * 10;
    this.speed = 1.75 + tier * 0.16 + Math.random() * 0.45;
    this.hitMeshes = [];
    this.nextShot = 0.7 + Math.random() * 0.8;
    this.losTimer = 0;
    this.los = false;
    this.strafeDir = Math.random() < 0.5 ? -1 : 1;
    this.strafeTimer = 1 + Math.random() * 2;
    this.avoidTimer = 0;
    this.moving = false;

    const parts = createSoldier(this.hitMeshes, tier);
    this.parts = parts;
    this.root = parts.root;
    this.root.position.copy(this.position);
    this.root.rotation.y = Math.random() * Math.PI * 2;
    for (const m of this.hitMeshes) m.userData.enemy = this;
    game.scene.add(this.root);

    this.muzzleWorld = new THREE.Vector3();
    this.flashT = 0;
  }

  get aimPoint() {
    return _v1.set(this.position.x, 1.35, this.position.z);
  }

  update(dt, time) {
    if (!this.alive) {
      this.deadT += dt;
      const fall = Math.min(1, this.deadT * 3.1);
      this.root.rotation.x = fall * 1.5;
      this.root.rotation.z = Math.sin(this.deadT * 2) * 0.08 * fall;
      this.root.position.y = this.deadT > 2.4 ? -(this.deadT - 2.4) * 0.55 : 0;
      if (this.deadT > 4.4 && !this.removed) {
        this.removed = true;
        this.game.scene.remove(this.root);
        this.dispose();
      }
      if (this.parts.flash.material.opacity > 0) this.parts.flash.material.opacity = 0;
      return;
    }

    const player = this.game.player;
    const px = player.pos.x, pz = player.pos.z;
    let dx = px - this.position.x, dz = pz - this.position.z;
    const dist = Math.hypot(dx, dz) || 0.001;
    dx /= dist; dz /= dist;

    this.spawnDelay -= dt;

    // Line of sight checks are throttled.
    this.losTimer -= dt;
    if (this.losTimer <= 0) {
      this.losTimer = 0.22 + Math.random() * 0.12;
      this.los = this.game.lineOfSight(
        _v2.set(this.position.x, 1.42, this.position.z),
        new THREE.Vector3(player.pos.x, player.pos.y + 1.4, player.pos.z)
      );
    }

    this.strafeTimer -= dt;
    if (this.strafeTimer <= 0) {
      this.strafeTimer = 1.2 + Math.random() * 2.2;
      this.strafeDir *= -1;
    }

    // face the player
    const targetYaw = Math.atan2(-dx, -dz);
    let dy = targetYaw - this.root.rotation.y;
    while (dy > Math.PI) dy -= Math.PI * 2;
    while (dy < -Math.PI) dy += Math.PI * 2;
    this.root.rotation.y += dy * Math.min(1, dt * 7);

    // desired movement
    let mx = 0, mz = 0;
    if (this.spawnDelay <= 0) {
      if (!this.los || dist > 17) {
        mx = dx; mz = dz;
      } else if (dist < 7) {
        mx = -dx; mz = -dz;
      } else {
        // strafe with slight approach bias
        mx = -dz * this.strafeDir + dx * 0.15;
        mz = dx * this.strafeDir + dz * 0.15;
      }
      // obstacle avoidance — steer perpendicular when blocked
      if (this.avoidTimer > 0) {
        this.avoidTimer -= dt;
        mx = -dz * this.strafeDir; mz = dx * this.strafeDir;
      }
      const len = Math.hypot(mx, mz) || 1;
      mx = mx / len * this.speed * dt;
      mz = mz / len * this.speed * dt;

      // separation from other enemies
      for (const other of this.game.enemies) {
        if (other === this || !other.alive) continue;
        const ox = this.position.x - other.position.x;
        const oz = this.position.z - other.position.z;
        const od = Math.hypot(ox, oz);
        if (od > 0.001 && od < 1.15) {
          mx += (ox / od) * dt * 1.8;
          mz += (oz / od) * dt * 1.8;
        }
      }

      const moved = this.game.moveEntity(this.position, mx, mz, 0.44);
      this.moving = moved > 0.0005;
      if (this.moving && moved < Math.hypot(mx, mz) * 0.45 && this.avoidTimer <= 0) {
        this.avoidTimer = 0.5 + Math.random() * 0.7;
        this.strafeDir *= -1;
      }
      this.walkPhase += dt * (this.moving ? 7.5 : 2.0);
    }

    // animation
    const swing = this.moving ? Math.sin(this.walkPhase) * 0.62 : Math.sin(this.walkPhase) * 0.05;
    for (const leg of this.parts.legs) {
      leg.hip.rotation.x = swing * (leg.phase ? -1 : 1);
      leg.shin.rotation.x = Math.max(0, -swing * (leg.phase ? -1 : 1)) * 0.7;
    }
    this.parts.model.position.y = this.moving ? Math.abs(Math.sin(this.walkPhase)) * 0.045 : 0;
    this.parts.model.rotation.z = this.moving ? Math.sin(this.walkPhase) * 0.025 : 0;
    this.parts.marker.material.opacity = 0.12 + Math.sin(time * 3 + this.walkPhase) * 0.06;

    // attack
    if (this.spawnDelay <= 0 && this.los && dist < 34) {
      this.nextShot -= dt;
      if (this.nextShot <= 0) {
        this.nextShot = Math.max(0.32, (0.95 - this.tier * 0.055)) * (0.75 + Math.random() * 0.6);
        this.shoot(dist);
      }
    }

    if (this.flashT > 0) {
      this.flashT -= dt;
      this.parts.flash.material.opacity = Math.max(0, this.flashT * 22);
      if (this.flashT <= 0) this.parts.flash.material.opacity = 0;
    }
  }

  shoot(dist) {
    const game = this.game;
    const player = game.player;
    this.parts.muzzle.getWorldPosition(this.muzzleWorld);
    this.parts.flash.material.rotation = Math.random() * Math.PI;
    this.parts.flash.material.opacity = 0.95;
    this.parts.flash.scale.setScalar(0.55 + Math.random() * 0.35);
    this.flashT = 0.055;

    // hit chance based on range, tier and player movement
    let chance = 0.62 - dist * 0.012 + this.tier * 0.028;
    if (player.sprinting) chance -= 0.12;
    chance = Math.max(0.12, Math.min(0.72, chance));
    const hit = Math.random() < chance;

    const aim = new THREE.Vector3(player.pos.x, player.pos.y + 1.35, player.pos.z);
    if (!hit) {
      aim.x += (Math.random() - 0.5) * 2.4;
      aim.y += (Math.random() - 0.5) * 1.5;
      aim.z += (Math.random() - 0.5) * 2.4;
    }
    game.addTracer(this.muzzleWorld, aim, 0xff7b3a, 0.055);
    game.audio.enemyShot(dist);

    if (hit) {
      const dmg = (5.5 + this.tier * 1.15) * (0.8 + Math.random() * 0.4);
      game.damagePlayer(dmg, this.position);
    }
    // small impact where the round lands
    if (!hit) {
      const dir = aim.clone().sub(this.muzzleWorld).normalize();
      const target = this.muzzleWorld.clone().addScaledVector(dir, 60);
      game.addImpactRay(this.muzzleWorld, target);
    }
  }

  takeDamage(amount, point, headshot) {
    if (!this.alive) return false;
    this.health -= amount;
    this.game.spawnBlood(point, headshot);
    this.game.audio.hit(headshot);
    if (this.health <= 0) {
      this.die(headshot);
      return true;
    }
    return false;
  }

  die(headshot) {
    this.alive = false;
    this.deadT = 0;
    // drop the rifle
    const rifle = this.parts.muzzle.parent;
    if (rifle) {
      rifle.visible = false;
    }
    this.parts.flash.material.opacity = 0;
    this.game.onEnemyKilled(this, headshot);
  }

  dispose() {
    this.root.traverse((o) => {
      if (o.geometry) o.geometry.dispose();
      if (o.material) {
        if (Array.isArray(o.material)) o.material.forEach(m => m.dispose());
        else o.material.dispose();
      }
    });
  }
}

import * as THREE from 'three';
import { createWorld } from './world.js';
import { createRifle } from './weapons.js';
import { Enemy } from './enemies.js';
import { ui } from './ui.js';

const EYE = 1.7;
const CROUCH_EYE = 1.12;
const RADIUS = 0.42;
const MAG_SIZE = 30;
const RELOAD_TIME = 1.85;

const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const damp = (a, b, lambda, dt) => a + (b - a) * (1 - Math.exp(-lambda * dt));
const rand = (a, b) => a + Math.random() * (b - a);

const _forward = new THREE.Vector3();
const _right = new THREE.Vector3();
const _dir = new THREE.Vector3();
const _origin = new THREE.Vector3();
const _tmp = new THREE.Vector3();

export class Game {
  constructor({ renderer, scene, camera, audio }) {
    this.renderer = renderer;
    this.scene = scene;
    this.camera = camera;
    this.audio = audio;
    this.world = createWorld(scene);

    this.rig = new THREE.Group();
    scene.add(this.rig);
    this.rig.add(camera);
    this.rig.position.set(0, EYE, 30);

    this.weapon = createRifle();
    this.weapon.group.visible = false;
    camera.add(this.weapon.group);

    this.raycaster = new THREE.Raycaster();
    this.raycaster.far = 200;

    this.enemies = [];
    this.effects = [];
    this.decals = [];
    this.grenades = [];

    this.mode = 'menu';
    this.time = 0;
    this.menuTime = 0;
    this.aimT = 0;
    this.recoil = 0;
    this.recoilPitch = 0;
    this.flashT = 0;
    this.shake = 0;
    this.lookSwayX = 0;
    this.lookSwayY = 0;
    this.hudTimer = 0;
    this.radarTimer = 0;
    this.stepTimer = 0;
    this.grenadeCooldown = 0;
    this.touch = matchMedia('(pointer: coarse)').matches || 'ontouchstart' in window;
    this.sensitivity = parseFloat(localStorage.getItem('nf-sens') || '1') || 1;
    this.invertY = localStorage.getItem('nf-invert') === '1';
    this.adsHeld = false;
    this.adsToggle = false;
    this.crouch = false;
    this.firing = false;
    this.touchMove = { x: 0, z: 0 };
    this.touchLook = null;
    this.joy = null;
    this.keys = {};

    this.resetStats();
    this.bindInput();
    this.setMenuCamera();
    ui.setMobile(this.touch);
  }

  resetStats() {
    this.player = {
      pos: new THREE.Vector3(0, 0, 30),
      vel: new THREE.Vector3(),
      velY: 0,
      yaw: 0,
      pitch: 0,
      health: 100,
      ammo: MAG_SIZE,
      reserve: 150,
      reloading: false,
      reloadT: 0,
      grounded: true,
      sprinting: false,
      lastDamage: -99,
      eye: EYE,
    };
    this.wave = 0;
    this.score = 0;
    this.kills = 0;
    this.shotsFired = 0;
    this.shotsHit = 0;
    this.grenadesLeft = 3;
    this.waveState = { phase: 'idle', toSpawn: 0, alive: 0, spawnTimer: 0, intermission: 0 };
    this.aimT = 0;
    this.recoil = 0;
    this.recoilPitch = 0;
    this.flashT = 0;
    this.shake = 0;
  }

  clearEntities() {
    for (const e of this.enemies) {
      this.scene.remove(e.root);
      e.dispose();
    }
    this.enemies.length = 0;
    for (const fx of this.effects) fx.dispose?.();
    this.effects.length = 0;
    for (const d of this.decals) {
      this.scene.remove(d.mesh);
      d.mesh.geometry.dispose(); d.mesh.material.dispose();
    }
    this.decals.length = 0;
    for (const g of this.grenades) {
      this.scene.remove(g.mesh);
      g.mesh.geometry.dispose(); g.mesh.material.dispose();
    }
    this.grenades.length = 0;
  }

  setMenuCamera() {
    this.rig.position.set(0, 4.4, 34);
    this.rig.rotation.set(0, 0, 0);
    this.camera.rotation.set(0, 0, 0);
    this.camera.fov = 62;
    this.camera.updateProjectionMatrix();
    this.camera.lookAt(0, 2.2, 0);
    this.weapon.group.visible = false;
  }

  start() {
    this.clearEntities();
    this.resetStats();
    this.player.pos.set(0, 0, 30);
    this.player.yaw = 0;
    this.player.pitch = -0.02;
    this.rig.position.set(0, EYE, 30);
    this.rig.rotation.set(0, 0, 0);
    this.camera.rotation.set(0, 0, 0);
    this.camera.fov = 76;
    this.camera.updateProjectionMatrix();
    this.weapon.group.visible = true;
    this.weapon.group.position.set(0.24, -0.215, -0.46);
    this.weapon.group.rotation.set(0, 0.035, -0.015);
    this.mode = 'playing';
    this.firing = false;
    this.adsHeld = false;
    this.adsToggle = false;
    this.crouch = false;
    this.wave = 0;
    ui.showHUD();
    ui.banner('OPERATION BLACKOUT', 'HOLD THE ZONE', 'CLEAR EVERY WAVE', 2600);
    this.startWave();
    if (!this.touch) this.requestLock();
  }

  restart() { this.start(); }

  requestLock() {
    if (this.touch) return;
    const canvas = this.renderer.domElement;
    if (document.pointerLockElement !== canvas) {
      const p = canvas.requestPointerLock?.();
      if (p && p.catch) p.catch(() => {});
    }
  }

  toMenu() {
    this.mode = 'menu';
    this.firing = false;
    this.clearEntities();
    this.resetStats();
    this.weapon.group.visible = false;
    ui.showMenu();
    this.setMenuCamera();
    if (document.pointerLockElement) document.exitPointerLock();
  }

  pause() {
    if (this.mode !== 'playing') return;
    this.mode = 'paused';
    this.firing = false;
    this.adsHeld = false;
    this.keys = {};
    this.touchMove.x = this.touchMove.z = 0;
    if (this.touchLook) { this.touchLook = null; this.resetJoystick(); }
    ui.showPause(this.wave, this.score);
    if (document.pointerLockElement) document.exitPointerLock();
  }

  resume() {
    if (this.mode !== 'paused') return;
    this.mode = 'playing';
    ui.showHUD();
    this.requestLock();
  }

  gameOver() {
    if (this.mode !== 'playing') return;
    this.mode = 'over';
    this.firing = false;
    const accuracy = this.shotsFired ? Math.round(this.shotsHit / this.shotsFired * 100) : 0;
    ui.showGameOver({
      waves: Math.max(0, this.wave - 1),
      kills: this.kills,
      accuracy,
      score: this.score,
    });
    if (document.pointerLockElement) document.exitPointerLock();
    this.audio.hurt();
  }

  /* ------------------------------------------------------------------ */
  bindInput() {
    const canvas = this.renderer.domElement;

    window.addEventListener('keydown', (e) => {
      if (e.code === 'Tab') e.preventDefault();
      if (this.keys[e.code]) return;
      this.keys[e.code] = true;
      if (e.code === 'Escape') {
        if (this.mode === 'playing') this.pause();
        else if (this.mode === 'paused') this.resume();
        return;
      }
      if (this.mode !== 'playing') return;
      if (e.code === 'KeyR') this.reload();
      if (e.code === 'KeyG') this.throwGrenade();
      if (e.code === 'KeyC') this.crouch = !this.crouch;
      if (e.code === 'Space') e.preventDefault();
    });
    window.addEventListener('keyup', (e) => { this.keys[e.code] = false; });
    window.addEventListener('blur', () => {
      this.keys = {};
      this.firing = false;
      this.adsHeld = false;
      if (this.mode === 'playing') this.pause();
    });

    canvas.addEventListener('mousedown', (e) => {
      if (this.touch || this.mode !== 'playing') return;
      if (document.pointerLockElement !== canvas) {
        this.requestLock();
        return;
      }
      if (e.button === 0) this.firing = true;
      if (e.button === 2) this.adsHeld = true;
    });
    window.addEventListener('mouseup', (e) => {
      if (e.button === 0) this.firing = false;
      if (e.button === 2) this.adsHeld = false;
    });
    window.addEventListener('mousemove', (e) => {
      if (this.touch || this.mode !== 'playing') return;
      if (document.pointerLockElement !== canvas) return;
      const s = 0.0021 * this.sensitivity;
      this.player.yaw -= e.movementX * s;
      this.player.pitch -= e.movementY * s * (this.invertY ? -1 : 1);
      this.player.pitch = clamp(this.player.pitch, -1.42, 1.42);
      this.lookSwayX = clamp(this.lookSwayX - e.movementX * 0.0005, -0.04, 0.04);
      this.lookSwayY = clamp(this.lookSwayY - e.movementY * 0.0004, -0.03, 0.03);
    });
    canvas.addEventListener('contextmenu', (e) => e.preventDefault());

    document.addEventListener('pointerlockchange', () => {
      if (!document.pointerLockElement && this.mode === 'playing' && !this.touch) this.pause();
    });

    /* ---------------- touch ---------------- */
    const joyBase = document.getElementById('joy-base');
    const joyKnob = document.getElementById('joy-knob');
    if (joyBase) {
      const setJoy = (e) => {
        const r = joyBase.getBoundingClientRect();
        const cx = r.left + r.width / 2, cy = r.top + r.height / 2;
        let dx = e.clientX - cx, dy = e.clientY - cy;
        const max = r.width / 2 - 12;
        const len = Math.hypot(dx, dy);
        if (len > max) { dx = dx / len * max; dy = dy / len * max; }
        joyKnob.style.transform = `translate(${dx}px, ${dy}px)`;
        this.touchMove.x = dx / max;
        this.touchMove.z = -dy / max;
      };
      joyBase.addEventListener('pointerdown', (e) => {
        e.preventDefault(); e.stopPropagation();
        this.joy = e.pointerId;
        joyBase.setPointerCapture(e.pointerId);
        setJoy(e);
      });
      joyBase.addEventListener('pointermove', (e) => {
        if (this.joy !== e.pointerId) return;
        e.preventDefault(); setJoy(e);
      });
      const endJoy = (e) => {
        if (this.joy !== e.pointerId) return;
        this.joy = null; this.resetJoystick();
      };
      joyBase.addEventListener('pointerup', endJoy);
      joyBase.addEventListener('pointercancel', endJoy);
    }

    canvas.addEventListener('pointerdown', (e) => {
      if (!this.touch || this.mode !== 'playing' || e.pointerType === 'mouse') return;
      if (this.touchLook) return;
      this.touchLook = { id: e.pointerId, x: e.clientX, y: e.clientY };
      canvas.setPointerCapture(e.pointerId);
    });
    canvas.addEventListener('pointermove', (e) => {
      if (!this.touch || !this.touchLook || this.touchLook.id !== e.pointerId) return;
      const dx = e.clientX - this.touchLook.x;
      const dy = e.clientY - this.touchLook.y;
      this.touchLook.x = e.clientX;
      this.touchLook.y = e.clientY;
      const s = 0.0048 * this.sensitivity;
      this.player.yaw -= dx * s;
      this.player.pitch -= dy * s * (this.invertY ? -1 : 1);
      this.player.pitch = clamp(this.player.pitch, -1.42, 1.42);
    });
    const endLook = (e) => {
      if (this.touchLook && this.touchLook.id === e.pointerId) this.touchLook = null;
    };
    canvas.addEventListener('pointerup', endLook);
    canvas.addEventListener('pointercancel', endLook);

    this.bindTouchButton('btn-touch-fire', (down) => { this.firing = down; });
    this.bindTouchButton('btn-touch-ads', (down) => { this.adsToggle = down; this.adsHeld = down; }, true);
    this.bindTouchButton('btn-touch-reload', () => this.reload(), false, true);
    this.bindTouchButton('btn-touch-jump', () => { if (this.player.grounded) this.player.velY = 5.4; }, false, true);
    this.bindTouchButton('btn-touch-grenade', () => this.throwGrenade(), false, true);
  }

  bindTouchButton(id, fn, hold = false, tap = false) {
    const el = document.getElementById(id);
    if (!el) return;
    el.addEventListener('pointerdown', (e) => {
      e.preventDefault(); e.stopPropagation();
      el.classList.add('pressed');
      if (tap) { fn(true); setTimeout(() => el.classList.remove('pressed'), 140); return; }
      fn(true);
      if (hold) {
        const up = () => {
          el.classList.remove('pressed');
          fn(false);
          el.removeEventListener('pointerup', up);
          el.removeEventListener('pointercancel', up);
        };
        el.addEventListener('pointerup', up);
        el.addEventListener('pointercancel', up);
      } else {
        setTimeout(() => el.classList.remove('pressed'), 140);
      }
    });
  }

  resetJoystick() {
    this.touchMove.x = 0; this.touchMove.z = 0;
    const knob = document.getElementById('joy-knob');
    if (knob) knob.style.transform = 'translate(0px, 0px)';
  }

  /* ------------------------------------------------------------------ */
  update(dt) {
    this.time += dt;
    this.world.update(dt, this.time);

    if (this.mode === 'menu') {
      this.updateMenuCamera(dt);
      this.updateEffects(dt);
      return;
    }
    if (this.mode === 'paused' || this.mode === 'over') {
      this.updateEffects(dt * 0.15);
      return;
    }

    this.updatePlayer(dt);
    this.updateWeapon(dt);
    this.updateEnemies(dt);
    this.updateGrenades(dt);
    this.updateEffects(dt);
    this.updateWaves(dt);
    this.updateAim(dt);
    this.updateCamera(dt);
    this.updateHud(dt);
  }

  updateMenuCamera(dt) {
    this.menuTime += dt;
    const a = this.menuTime * 0.045;
    this.rig.position.set(Math.sin(a) * 26, 4.2 + Math.sin(a * 1.7) * 0.9, Math.cos(a) * 26);
    this.rig.rotation.set(0, 0, 0);
    this.camera.rotation.set(0, 0, 0);
    this.camera.lookAt(Math.sin(a * 0.7) * 6, 2.1 + Math.sin(a * 1.3) * 0.4, Math.cos(a * 0.7) * 6 - 5);
  }

  updatePlayer(dt) {
    const p = this.player;
    const k = this.keys;
    let ix = (k.KeyD ? 1 : 0) - (k.KeyA ? 1 : 0) + this.touchMove.x;
    let iz = (k.KeyW ? 1 : 0) - (k.KeyS ? 1 : 0) + this.touchMove.z;
    const ilen = Math.hypot(ix, iz);
    if (ilen > 1) { ix /= ilen; iz /= ilen; }

    const aimHeld = this.adsHeld || this.adsToggle;
    const sprint = (k.ShiftLeft || k.ShiftRight) && iz > 0.35 && !aimHeld && !this.firing;
    p.sprinting = sprint;
    const speed = this.crouch ? 3.1 : sprint ? 8.3 : aimHeld ? 3.8 : 5.5;

    _forward.set(-Math.sin(p.yaw), 0, -Math.cos(p.yaw));
    _right.set(Math.cos(p.yaw), 0, -Math.sin(p.yaw));
    const wx = (_forward.x * iz + _right.x * ix) * speed;
    const wz = (_forward.z * iz + _right.z * ix) * speed;

    p.vel.x = damp(p.vel.x, wx, p.grounded ? 13 : 3.5, dt);
    p.vel.z = damp(p.vel.z, wz, p.grounded ? 13 : 3.5, dt);

    if (k.Space && p.grounded) {
      p.velY = 5.3;
      p.grounded = false;
      k.Space = false;
      this.audio.footstep(true);
    }
    if (!p.grounded) {
      p.velY -= 16.5 * dt;
      p.pos.y += p.velY * dt;
      if (p.pos.y <= 0) {
        p.pos.y = 0; p.velY = 0; p.grounded = true;
        this.audio.footstep(this.touchMove.z > 0.2);
      }
    }

    const moved = this.moveEntity(p.pos, p.vel.x * dt, p.vel.z * dt, RADIUS);
    if (moved < 0.001) { p.vel.x *= 0.8; p.vel.z *= 0.8; }

    const horiz = Math.hypot(p.vel.x, p.vel.z);
    this.stepTimer -= dt;
    if (p.grounded && horiz > 1.2 && this.stepTimer <= 0) {
      this.stepTimer = sprint ? 0.32 : 0.48;
      this.audio.footstep(sprint);
    }

    // crouch eye height
    const targetEye = this.crouch ? CROUCH_EYE : EYE;
    p.eye = damp(p.eye, targetEye, 12, dt);
    const bob = p.grounded ? Math.sin(this.time * (sprint ? 14 : 10)) * Math.min(0.045, horiz * 0.008) : 0;
    const sideBob = p.grounded ? Math.cos(this.time * (sprint ? 7 : 5)) * Math.min(0.02, horiz * 0.003) : 0;
    this.rig.position.set(p.pos.x + sideBob * 0.3, p.pos.y + p.eye + bob, p.pos.z);

    // regeneration
    if (this.time - p.lastDamage > 5.5 && p.health < 100 && p.health > 0) {
      p.health = Math.min(100, p.health + 7.5 * dt);
    }
    if (p.reloading) {
      p.reloadT += dt;
      if (p.reloadT >= RELOAD_TIME) {
        const need = MAG_SIZE - p.ammo;
        const take = Math.min(need, p.reserve);
        p.ammo += take;
        p.reserve -= take;
        p.reloading = false;
        p.reloadT = 0;
        this.audio.reloadEnd();
      }
    }
  }

  updateAim(dt) {
    const target = (this.adsHeld || this.adsToggle || (this.touchMove.x === 0 && false)) ? 1 : 0;
    this.aimT = damp(this.aimT, target, 14, dt);
  }

  updateCamera(dt) {
    const p = this.player;
    this.rig.rotation.y = p.yaw;
    this.recoilPitch = damp(this.recoilPitch, 0, 7.5, dt);
    this.shake = damp(this.shake, 0, 8, dt);
    const sh = this.shake;
    this.camera.rotation.x = p.pitch + this.recoilPitch + (Math.random() - 0.5) * sh * 0.055;
    this.camera.rotation.z = -this.touchMove.x * 0.012 + (Math.random() - 0.5) * sh * 0.07;
    this.camera.position.y = (Math.random() - 0.5) * sh * 0.04;
    const fov = 76 - this.aimT * 22 + (p.sprinting ? 5 : 0);
    if (Math.abs(this.camera.fov - fov) > 0.01) {
      this.camera.fov = fov;
      this.camera.updateProjectionMatrix();
    }
    this.lookSwayX = damp(this.lookSwayX, 0, 9, dt);
    this.lookSwayY = damp(this.lookSwayY, 0, 9, dt);
  }

  updateWeapon(dt) {
    const p = this.player;
    const g = this.weapon.group;
    if (!g.visible) return;

    const aim = this.aimT;
    const hip = { x: 0.24, y: -0.215, z: -0.46 };
    const ads = { x: 0, y: -0.148, z: -0.40 };
    const speed = Math.hypot(p.vel.x, p.vel.z);
    const bobScale = (1 - aim * 0.82) * (p.grounded ? 1 : 0.25);
    const bobX = Math.sin(this.time * 9) * 0.008 * Math.min(1, speed / 5) * bobScale;
    const bobY = Math.abs(Math.cos(this.time * 9)) * 0.008 * Math.min(1, speed / 5) * bobScale;
    const sprintDrop = p.sprinting ? 1 : 0;

    const reloadBend = p.reloading ? Math.sin(Math.min(1, p.reloadT / RELOAD_TIME) * Math.PI) : 0;

    g.position.x = damp(g.position.x, hip.x + (ads.x - hip.x) * aim + bobX + this.lookSwayX, 16, dt);
    g.position.y = damp(g.position.y, hip.y + (ads.y - hip.y) * aim - bobY + this.lookSwayY - sprintDrop * 0.055 - reloadBend * 0.09, 16, dt);
    g.position.z = damp(g.position.z, hip.z + (ads.z - hip.z) * aim + this.recoil * 0.035, 16, dt);
    g.rotation.x = damp(g.rotation.x, this.recoil * 0.08 + reloadBend * 0.32, 14, dt);
    g.rotation.y = damp(g.rotation.y, 0.035 * (1 - aim) + this.lookSwayX * 0.5, 14, dt);
    g.rotation.z = damp(g.rotation.z, -0.015 * (1 - aim) - this.lookSwayX * 0.8 + reloadBend * 0.25, 14, dt);

    this.recoil = damp(this.recoil, 0, 13, dt);

    // firing
    if (this.firing && !p.reloading) {
      if (p.ammo > 0) {
        this.tryFire();
      } else if (p.reserve > 0) {
        this.reload();
      } else if (this.time > (this._dryTime || 0)) {
        this._dryTime = this.time + 0.35;
        this.audio.dry();
      }
    }

    // muzzle flash decay
    if (this.flashT > 0) {
      this.flashT -= dt;
      const f = Math.max(0, this.flashT / 0.05);
      this.weapon.flash.material.opacity = f;
      this.weapon.flashLight.intensity = f * 14;
    } else {
      this.weapon.flash.material.opacity = 0;
      this.weapon.flashLight.intensity = 0;
    }

    // crosshair
    const spread = 7 + Math.min(10, speed * 0.55) + (p.grounded ? 0 : 6) + this.recoil * 5 - aim * 4.5;
    ui.setCrosshair(spread, aim > 0.55);
  }

  tryFire() {
    const p = this.player;
    if (this.time < (this.nextShot || 0)) return;
    if (p.ammo <= 0) return;
    this.nextShot = this.time + 0.088;
    p.ammo--;
    this.shotsFired++;

    const moving = Math.hypot(p.vel.x, p.vel.z) > 1;
    const spread = (this.aimT > 0.6 ? 0.0022 : 0.007) + (moving ? 0.009 : 0) + (p.grounded ? 0 : 0.02) + this.recoil * 0.006;
    this.camera.getWorldPosition(_origin);
    _dir.set(0, 0, -1).applyQuaternion(this.camera.getWorldQuaternion(new THREE.Quaternion()));
    _dir.x += rand(-spread, spread);
    _dir.y += rand(-spread, spread);
    _dir.z += rand(-spread, spread) * 0.3;
    _dir.normalize();

    this.raycaster.set(_origin, _dir);
    this.raycaster.far = 200;
    const targets = this.world.solidMeshes.slice();
    for (const e of this.enemies) if (e.alive) targets.push(...e.hitMeshes);
    const hits = this.raycaster.intersectObjects(targets, false);

    const muzzleWorld = this.weapon.muzzle.getWorldPosition(new THREE.Vector3());
    let end = null;
    let hitEnemy = false;

    if (hits.length) {
      const hit = hits[0];
      end = hit.point.clone();
      if (hit.object.userData.enemy && hit.object.userData.enemy.alive) {
        const enemy = hit.object.userData.enemy;
        const mult = hit.object.userData.hitMult || 1;
        const headshot = mult >= 3;
        const dmg = 34 * mult;
        const killed = enemy.takeDamage(dmg, hit.point.clone(), headshot);
        this.shotsHit++;
        ui.hitmarker(killed);
        hitEnemy = true;
      } else {
        const normal = hit.face
          ? hit.face.normal.clone().transformDirection(hit.object.matrixWorld)
          : _dir.clone().negate();
        this.addImpact(hit.point, normal, hit.object.userData.solid);
      }
    } else {
      end = _origin.clone().addScaledVector(_dir, 120);
    }

    if (!hitEnemy) {
      const tracerEnd = end || _origin.clone().addScaledVector(_dir, 60);
      this.addTracer(muzzleWorld, tracerEnd, 0xffd79a, 0.055);
    } else {
      this.addTracer(muzzleWorld, end, 0xffe2b0, 0.045);
    }

    // muzzle flash + recoil
    this.flashT = 0.05;
    const mat = this.weapon.flash.material;
    mat.rotation = Math.random() * Math.PI * 2;
    mat.opacity = 1;
    this.weapon.flash.scale.setScalar(0.34 + Math.random() * 0.17);
    this.weapon.flashLight.intensity = 16;
    this.audio.shot();
    this.recoil = Math.min(1.9, this.recoil + 0.75);
    const kick = (this.aimT > 0.6 ? 0.0042 : 0.0085) * (0.85 + Math.random() * 0.3);
    this.player.pitch = clamp(this.player.pitch + kick, -1.42, 1.42);
    this.shake = Math.min(1, this.shake + 0.08);
    this.ejectShell();

    // ammo empty → auto reload after brief delay
    if (p.ammo === 0 && p.reserve > 0) {
      setTimeout(() => { if (this.mode === 'playing' && !this.player.reloading && this.player.ammo === 0) this.reload(); }, 260);
    }
  }

  reload() {
    const p = this.player;
    if (p.reloading || p.ammo >= MAG_SIZE || p.reserve <= 0 || this.mode !== 'playing') return;
    p.reloading = true;
    p.reloadT = 0;
    this.audio.reloadStart();
  }

  throwGrenade() {
    if (this.mode !== 'playing' || this.grenadesLeft <= 0 || this.grenadeCooldown > 0) return;
    this.grenadesLeft--;
    this.grenadeCooldown = 0.6;
    const camPos = this.camera.getWorldPosition(new THREE.Vector3());
    const dir = new THREE.Vector3(0, 0, -1).applyQuaternion(this.camera.getWorldQuaternion(new THREE.Quaternion()));
    const mesh = new THREE.Mesh(
      new THREE.SphereGeometry(0.1, 10, 8),
      new THREE.MeshStandardMaterial({ color: 0x27302a, roughness: 0.6, metalness: 0.4, emissive: 0xff2e18, emissiveIntensity: 0.22 })
    );
    mesh.position.copy(camPos).addScaledVector(dir, 0.7);
    mesh.castShadow = true;
    this.scene.add(mesh);
    const vel = dir.clone().multiplyScalar(15).add(new THREE.Vector3(0, 3.2, 0)).add(this.player.vel.clone().multiplyScalar(0.5));
    this.grenades.push({ mesh, vel, fuse: 2.35 });
    this.audio.footstep(true);
  }

  updateGrenades(dt) {
    this.grenadeCooldown = Math.max(0, this.grenadeCooldown - dt);
    for (let i = this.grenades.length - 1; i >= 0; i--) {
      const g = this.grenades[i];
      g.fuse -= dt;
      g.vel.y -= 17 * dt;
      g.mesh.position.addScaledVector(g.vel, dt);
      g.mesh.rotation.x += dt * 6;
      g.mesh.rotation.z += dt * 4;
      if (g.mesh.position.y < 0.1) {
        g.mesh.position.y = 0.1;
        g.vel.y *= -0.4;
        g.vel.x *= 0.72; g.vel.z *= 0.72;
        if (Math.abs(g.vel.y) < 0.5) g.vel.y = 0;
      }
      if (Math.abs(g.mesh.position.x) > 46) { g.mesh.position.x = clamp(g.mesh.position.x, -46, 46); g.vel.x *= -0.5; }
      if (Math.abs(g.mesh.position.z) > 46) { g.mesh.position.z = clamp(g.mesh.position.z, -46, 46); g.vel.z *= -0.5; }
      // bounce off crates
      for (const c of this.world.colliders) {
        const p = g.mesh.position;
        if (p.x > c.min.x - 0.1 && p.x < c.max.x + 0.1 && p.z > c.min.z - 0.1 && p.z < c.max.z + 0.1 && p.y < c.max.y + 0.1) {
          if (p.y > c.min.y + 0.05) {
            p.y = c.max.y + 0.12;
            g.vel.y = Math.abs(g.vel.y) * 0.35;
          }
        }
      }
      if (g.fuse <= 0) {
        this.explode(g.mesh.position.clone());
        this.scene.remove(g.mesh);
        g.mesh.geometry.dispose(); g.mesh.material.dispose();
        this.grenades.splice(i, 1);
      }
    }
  }

  explode(pos) {
    this.audio.explosion();
    const flashGeo = new THREE.SphereGeometry(0.6, 16, 12);
    const flashMat = new THREE.MeshBasicMaterial({ color: 0xffd28a, transparent: true, opacity: 1, blending: THREE.AdditiveBlending, depthWrite: false });
    const flash = new THREE.Mesh(flashGeo, flashMat);
    flash.position.copy(pos); this.scene.add(flash);
    const light = new THREE.PointLight(0xff8a3a, 120, 30, 2);
    light.position.copy(pos).add(new THREE.Vector3(0, 0.6, 0)); this.scene.add(light);
    let t = 0;
    this.addEffect({
      update: (dt) => {
        t += dt;
        flash.scale.setScalar(1 + t * 9);
        flashMat.opacity = Math.max(0, 1 - t * 2.4);
        light.intensity = Math.max(0, 120 * (1 - t * 3));
        if (t > 0.55) { light.intensity = 0; return false; }
        return true;
      },
      dispose: () => { this.scene.remove(flash); this.scene.remove(light); flashGeo.dispose(); flashMat.dispose(); },
    });
    this.addSparks(pos, 46, 0xffa54a, 10, 0.018);
    this.addSmoke(pos, 16, 0x2a2622, 1.0);

    // damage
    for (const e of this.enemies) {
      if (!e.alive) continue;
      const d = e.position.distanceTo(pos);
      if (d < 8) {
        const dmg = 170 * (1 - d / 8) + 25;
        const killed = e.takeDamage(dmg, e.position.clone().add(new THREE.Vector3(0, 1.2, 0)), false);
        if (killed) ui.hitmarker(true);
      }
    }
    const pd = new THREE.Vector3(this.player.pos.x, 0, this.player.pos.z).distanceTo(pos);
    if (pd < 5.4) this.damagePlayer(38 * (1 - pd / 5.4), pos);
    this.shake = Math.min(1.3, this.shake + 0.9);
  }

  /* ------------------------------------------------------------------ */
  updateEnemies(dt) {
    for (const e of this.enemies) e.update(dt, this.time);
    // keep array tidy
    if (this.enemies.length > 24) {
      this.enemies = this.enemies.filter(e => !e.removed);
    }
  }

  updateWaves(dt) {
    const ws = this.waveState;
    if (ws.phase === 'idle') return;

    if (ws.phase === 'intermission') {
      ws.intermission -= dt;
      if (ws.intermission <= 0) this.startWave();
      return;
    }

    if (ws.phase === 'active') {
      if (ws.toSpawn > 0) {
        ws.spawnTimer -= dt;
        if (ws.spawnTimer <= 0) {
          const maxAlive = Math.min(4 + Math.floor(this.wave / 2), 10);
          if (ws.alive < maxAlive) {
            this.spawnEnemy();
            ws.toSpawn--;
            ws.alive++;
            ws.spawnTimer = Math.max(0.45, 1.45 - this.wave * 0.05) * (0.8 + Math.random() * 0.4);
          } else {
            ws.spawnTimer = 0.35;
          }
        }
      }
      if (ws.toSpawn <= 0 && ws.alive <= 0) {
        const bonus = 250 * this.wave;
        this.score += bonus;
        ws.phase = 'intermission';
        ws.intermission = 5.2;
        this.player.reserve = Math.min(300, this.player.reserve + 90);
        this.grenadesLeft = Math.min(4, this.grenadesLeft + 2);
        ui.banner('SECTOR CLEAR', `WAVE ${String(this.wave).padStart(2, '0')} CLEARED`, `+${bonus} · REARMING`, 2600);
        this.audio.wave();
      }
    }
  }

  startWave() {
    this.wave++;
    const count = Math.min(18, 4 + Math.ceil(this.wave * 1.6));
    this.waveState = {
      phase: 'active',
      toSpawn: count,
      alive: 0,
      spawnTimer: 0.5,
      intermission: 0,
    };
    ui.banner('INCOMING', `WAVE ${String(this.wave).padStart(2, '0')}`, `${count} HOSTILES · HOLD POSITION`, 2400);
    this.audio.wave();
  }

  spawnEnemy() {
    const p = this.player.pos;
    const candidates = this.world.spawnPoints.filter(sp => Math.hypot(sp.x - p.x, sp.z - p.z) > 15);
    let pos = (candidates.length ? candidates[Math.floor(Math.random() * candidates.length)] : this.world.spawnPoints[0]).clone();
    // avoid overlapping other enemies
    for (let attempt = 0; attempt < 6; attempt++) {
      const close = this.enemies.some(e => e.alive && e.position.distanceTo(pos) < 2.2);
      if (!close) break;
      pos = this.world.spawnPoints[Math.floor(Math.random() * this.world.spawnPoints.length)].clone();
    }
    const tier = 1 + Math.floor((this.wave - 1) / 2);
    const enemy = new Enemy(this, pos, tier);
    this.enemies.push(enemy);
    this.addSparks(pos.clone().add(new THREE.Vector3(0, 1, 0)), 18, 0xff4a20, 4, 0.03);
    this.addSmoke(pos.clone().add(new THREE.Vector3(0, 0.6, 0)), 6, 0x3a2018, 0.7);
  }

  moveEntity(pos, dx, dz, radius) {
    const sx = pos.x, sz = pos.z;
    pos.x += dx;
    pos.z += dz;
    for (let iter = 0; iter < 2; iter++) {
      for (const c of this.world.colliders) {
        const cx = clamp(pos.x, c.min.x, c.max.x);
        const cz = clamp(pos.z, c.min.z, c.max.z);
        let ox = pos.x - cx, oz = pos.z - cz;
        let d = Math.hypot(ox, oz);
        if (d < radius) {
          if (d < 0.0001) {
            // inside — push out along the shortest axis
            const left = Math.abs(pos.x - c.min.x), rightA = Math.abs(c.max.x - pos.x);
            const back = Math.abs(pos.z - c.min.z), front = Math.abs(c.max.z - pos.z);
            const m = Math.min(left, rightA, back, front);
            if (m === left) pos.x = c.min.x - radius;
            else if (m === rightA) pos.x = c.max.x + radius;
            else if (m === back) pos.z = c.min.z - radius;
            else pos.z = c.max.z + radius;
          } else {
            const push = (radius - d) / d;
            pos.x += ox * push;
            pos.z += oz * push;
          }
        }
      }
    }
    pos.x = clamp(pos.x, -46.4, 46.4);
    pos.z = clamp(pos.z, -46.4, 46.4);
    return Math.hypot(pos.x - sx, pos.z - sz);
  }

  lineOfSight(from, to) {
    _tmp.copy(to).sub(from);
    const dist = _tmp.length();
    if (dist < 0.01) return true;
    _tmp.multiplyScalar(1 / dist);
    this.raycaster.set(from, _tmp);
    this.raycaster.far = Math.max(0.1, dist - 0.25);
    const hits = this.raycaster.intersectObjects(this.world.solidMeshes, false);
    return hits.length === 0;
  }

  damagePlayer(amount, source) {
    const p = this.player;
    if (this.mode !== 'playing' || p.health <= 0) return;
    p.health -= amount;
    p.lastDamage = this.time;
    this.shake = Math.min(1.2, this.shake + amount * 0.018);

    const dx = source.x - p.pos.x, dz = source.z - p.pos.z;
    _forward.set(-Math.sin(p.yaw), 0, -Math.cos(p.yaw));
    _right.set(Math.cos(p.yaw), 0, -Math.sin(p.yaw));
    const angle = Math.atan2(dx * _right.x + dz * _right.z, dx * _forward.x + dz * _forward.z) * 180 / Math.PI;
    ui.damage(angle);
    this.audio.hurt();
    if (p.health <= 0) {
      p.health = 0;
      this.gameOver();
    }
  }

  onEnemyKilled(enemy, headshot) {
    this.waveState.alive = Math.max(0, this.waveState.alive - 1);
    this.kills++;
    this.score += 100 + (headshot ? 75 : 0) + this.wave * 10;
    ui.killfeed(headshot);
    ui.hitmarker(true);
    this.audio.kill();
    this.addSparks(enemy.position.clone().add(new THREE.Vector3(0, 1.1, 0)), 20, 0x9a1c12, 4, 0.035);
  }

  updateHud(dt) {
    this.hudTimer -= dt;
    if (this.hudTimer <= 0) {
      this.hudTimer = 0.09;
      ui.updateHUD({
        health: this.player.health,
        ammo: this.player.ammo,
        reserve: this.player.reserve,
        grenades: this.grenadesLeft,
        wave: this.wave,
        score: this.score,
        remaining: this.waveState.toSpawn + this.waveState.alive,
        reloading: this.player.reloading,
        reloadProgress: this.player.reloadT / RELOAD_TIME,
      });
    }
    this.radarTimer -= dt;
    if (this.radarTimer <= 0) {
      this.radarTimer = 0.07;
      ui.radar(this.enemies, this.player.pos, this.player.yaw, 0.07);
    }
    ui.updateCompass(this.player.yaw);
  }

  /* ------------------------------------------------------------------ */
  addEffect(effect) { this.effects.push(effect); }

  updateEffects(dt) {
    for (let i = this.effects.length - 1; i >= 0; i--) {
      const fx = this.effects[i];
      let alive = true;
      try { alive = fx.update(dt) !== false; } catch { alive = false; }
      if (!alive) {
        fx.dispose?.();
        this.effects.splice(i, 1);
      }
    }

    for (let i = this.decals.length - 1; i >= 0; i--) {
      const d = this.decals[i];
      d.life -= dt;
      if (d.life < 3) d.mesh.material.opacity = Math.max(0, d.life / 3 * d.opacity);
      if (d.life <= 0) {
        this.scene.remove(d.mesh);
        d.mesh.geometry.dispose();
        d.mesh.material.dispose();
        this.decals.splice(i, 1);
      }
    }
  }

  addTracer(start, end, color = 0xffd58a, life = 0.06) {
    const geo = new THREE.BufferGeometry().setFromPoints([start.clone(), end.clone()]);
    const mat = new THREE.LineBasicMaterial({ color, transparent: true, opacity: 0.9, blending: THREE.AdditiveBlending, depthWrite: false });
    const line = new THREE.Line(geo, mat);
    line.frustumCulled = false;
    this.scene.add(line);
    let t = 0;
    this.addEffect({
      update: (dt) => {
        t += dt;
        mat.opacity = Math.max(0, 0.9 * (1 - t / life));
        return t < life;
      },
      dispose: () => { this.scene.remove(line); geo.dispose(); mat.dispose(); },
    });
  }

  addImpact(point, normal, isWorld = true) {
    this.addSparks(point, isWorld ? 7 : 4, 0xffc07a, 3.2, 0.014);
    // decal
    const geo = new THREE.CircleGeometry(0.055 + Math.random() * 0.03, 7);
    const mat = new THREE.MeshBasicMaterial({
      color: 0x0b0a09, transparent: true, opacity: 0.82,
      polygonOffset: true, polygonOffsetFactor: -4, depthWrite: false,
    });
    const decal = new THREE.Mesh(geo, mat);
    decal.position.copy(point).addScaledVector(normal, 0.012);
    decal.lookAt(point.clone().add(normal));
    decal.rotateZ(Math.random() * Math.PI * 2);
    this.scene.add(decal);
    this.decals.push({ mesh: decal, life: 13, opacity: 0.82 });
    if (this.decals.length > 55) {
      const old = this.decals.shift();
      this.scene.remove(old.mesh);
      old.mesh.geometry.dispose(); old.mesh.material.dispose();
    }
  }

  addImpactRay(origin, target) {
    _tmp.copy(target).sub(origin);
    const dist = _tmp.length();
    _tmp.multiplyScalar(1 / dist);
    this.raycaster.set(origin, _tmp);
    this.raycaster.far = dist;
    const hits = this.raycaster.intersectObjects(this.world.solidMeshes, false);
    if (hits.length) {
      const h = hits[0];
      const n = h.face ? h.face.normal.clone().transformDirection(h.object.matrixWorld) : _tmp.clone().negate();
      this.addSparks(h.point, 4, 0xffb060, 2.6, 0.013);
    }
  }

  addSparks(pos, count, color, speed = 4, size = 0.02) {
    const positions = new Float32Array(count * 3);
    const velocities = [];
    for (let i = 0; i < count; i++) {
      positions[i * 3] = pos.x; positions[i * 3 + 1] = pos.y; positions[i * 3 + 2] = pos.z;
      const v = new THREE.Vector3(rand(-1, 1), rand(-0.2, 1), rand(-1, 1)).normalize().multiplyScalar(speed * (0.25 + Math.random()));
      velocities.push(v);
    }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    const mat = new THREE.PointsMaterial({ color, size, transparent: true, opacity: 1, blending: THREE.AdditiveBlending, depthWrite: false });
    const pts = new THREE.Points(geo, mat);
    this.scene.add(pts);
    let t = 0;
    const life = 0.4 + Math.random() * 0.25;
    this.addEffect({
      update: (dt) => {
        t += dt;
        const arr = geo.attributes.position.array;
        for (let i = 0; i < count; i++) {
          velocities[i].y -= 9 * dt;
          arr[i * 3] += velocities[i].x * dt;
          arr[i * 3 + 1] += velocities[i].y * dt;
          arr[i * 3 + 2] += velocities[i].z * dt;
        }
        geo.attributes.position.needsUpdate = true;
        mat.opacity = Math.max(0, 1 - t / life);
        return t < life;
      },
      dispose: () => { this.scene.remove(pts); geo.dispose(); mat.dispose(); },
    });
  }

  addSmoke(pos, count, color, spread = 1, size = 0.5) {
    const positions = new Float32Array(count * 3);
    for (let i = 0; i < count; i++) {
      positions[i * 3] = pos.x + rand(-spread, spread) * 0.35;
      positions[i * 3 + 1] = pos.y + rand(0, spread);
      positions[i * 3 + 2] = pos.z + rand(-spread, spread) * 0.35;
    }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    const mat = new THREE.PointsMaterial({ color, size, transparent: true, opacity: 0.35, depthWrite: false });
    const pts = new THREE.Points(geo, mat);
    this.scene.add(pts);
    let t = 0;
    const life = 1.6;
    this.addEffect({
      update: (dt) => {
        t += dt;
        const arr = geo.attributes.position.array;
        for (let i = 0; i < count; i++) {
          arr[i * 3 + 1] += dt * (0.5 + i % 4 * 0.18);
          arr[i * 3] += Math.sin(t + i) * dt * 0.15;
        }
        geo.attributes.position.needsUpdate = true;
        mat.opacity = Math.max(0, 0.35 * (1 - t / life));
        mat.size = size * (1 + t * 0.9);
        return t < life;
      },
      dispose: () => { this.scene.remove(pts); geo.dispose(); mat.dispose(); },
    });
  }

  spawnBlood(pos, headshot) {
    this.addSparks(pos, headshot ? 18 : 9, headshot ? 0xff3b2a : 0xaa2218, headshot ? 5 : 3.2, 0.026);
  }

  ejectShell() {
    const geo = new THREE.CylinderGeometry(0.011, 0.011, 0.045, 6);
    const mat = new THREE.MeshStandardMaterial({ color: 0xc39a3d, roughness: 0.35, metalness: 0.8 });
    const shell = new THREE.Mesh(geo, mat);
    this.weapon.ejectPort.getWorldPosition(shell.position);
    const vel = new THREE.Vector3(rand(1.2, 2.4), rand(0.8, 1.6), rand(-0.4, 0.4));
    vel.applyQuaternion(this.camera.getWorldQuaternion(new THREE.Quaternion()));
    this.scene.add(shell);
    let t = 0;
    this.addEffect({
      update: (dt) => {
        t += dt;
        vel.y -= 13 * dt;
        shell.position.addScaledVector(vel, dt);
        shell.rotation.x += dt * 12;
        shell.rotation.z += dt * 7;
        if (shell.position.y < 0.02) { shell.position.y = 0.02; vel.y *= -0.25; vel.x *= 0.5; vel.z *= 0.5; }
        return t < 1.6;
      },
      dispose: () => { this.scene.remove(shell); geo.dispose(); mat.dispose(); },
    });
  }
}

import * as THREE from 'three';
import { EffectComposer } from 'three/addons/postprocessing/EffectComposer.js';
import { RenderPass } from 'three/addons/postprocessing/RenderPass.js';
import { UnrealBloomPass } from 'three/addons/postprocessing/UnrealBloomPass.js';
import { OutputPass } from 'three/addons/postprocessing/OutputPass.js';
import { Game } from './game.js';
import { AudioEngine } from './audio.js';
import { ui } from './ui.js';

const $ = (id) => document.getElementById(id);
const isMobile = matchMedia('(pointer: coarse)').matches || 'ontouchstart' in window;

/* ------------------------------------------------------------------ */
/* Renderer                                                            */
/* ------------------------------------------------------------------ */
const canvas = $('game');
const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, powerPreference: 'high-performance', stencil: false });
renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, isMobile ? 1.6 : 2));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.04;
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;

const scene = new THREE.Scene();
const camera = new THREE.PerspectiveCamera(76, window.innerWidth / window.innerHeight, 0.04, 320);

const composer = new EffectComposer(renderer);
composer.addPass(new RenderPass(scene, camera));
const bloom = new UnrealBloomPass(new THREE.Vector2(window.innerWidth, window.innerHeight), 0.42, 0.55, 0.82);
composer.addPass(bloom);
composer.addPass(new OutputPass());

const audio = new AudioEngine();
ui.init();
ui.loader(0.15);

const game = new Game({ renderer, scene, camera, audio });
ui.loader(0.7);

/* ------------------------------------------------------------------ */
/* Settings                                                            */
/* ------------------------------------------------------------------ */
const settings = {
  sensitivity: parseFloat(localStorage.getItem('nf-sens') || '1') || 1,
  invert: localStorage.getItem('nf-invert') === '1',
  quality: localStorage.getItem('nf-quality') || (isMobile ? 'medium' : 'high'),
  sound: localStorage.getItem('nf-sound') !== '0',
};

function applyQuality(q) {
  settings.quality = q;
  localStorage.setItem('nf-quality', q);
  const cap = q === 'high' ? (isMobile ? 1.6 : 2) : q === 'medium' ? 1.35 : 1;
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, cap));
  composer.setPixelRatio(Math.min(window.devicePixelRatio || 1, cap));
  composer.setSize(window.innerWidth, window.innerHeight);
  renderer.shadowMap.enabled = q !== 'low';
  bloom.enabled = q === 'high';
}

function applySettingsToUI() {
  $('set-sens').value = settings.sensitivity;
  $('set-sens-val').textContent = settings.sensitivity.toFixed(2).replace(/0$/, '');
  $('set-quality').value = settings.quality;
  $('set-invert').checked = settings.invert;
  $('set-audio').checked = settings.sound;
  game.sensitivity = settings.sensitivity;
  game.invertY = settings.invert;
  audio.setEnabled(settings.sound);
}

applyQuality(settings.quality);
applySettingsToUI();

$('set-sens').addEventListener('input', (e) => {
  settings.sensitivity = parseFloat(e.target.value);
  localStorage.setItem('nf-sens', settings.sensitivity);
  game.sensitivity = settings.sensitivity;
  $('set-sens-val').textContent = settings.sensitivity.toFixed(2).replace(/0$/, '');
});
$('set-quality').addEventListener('change', (e) => applyQuality(e.target.value));
$('set-invert').addEventListener('change', (e) => {
  settings.invert = e.target.checked;
  localStorage.setItem('nf-invert', settings.invert ? '1' : '0');
  game.invertY = settings.invert;
});
$('set-audio').addEventListener('change', (e) => {
  settings.sound = e.target.checked;
  localStorage.setItem('nf-sound', settings.sound ? '1' : '0');
  audio.setEnabled(settings.sound);
});

/* ------------------------------------------------------------------ */
/* Menus                                                               */
/* ------------------------------------------------------------------ */
function deploy() {
  audio.init();
  audio.resume();
  audio.setEnabled(settings.sound);
  audio.ui();
  game.start();
}

$('btn-deploy').addEventListener('click', deploy);
$('btn-settings').addEventListener('click', () => { ui.showSettings(); });
$('btn-settings-close').addEventListener('click', () => { ui.closeSettings(); audio.ui(); });
$('btn-briefing').addEventListener('click', () => { ui.showBriefing(); });
$('btn-briefing-close').addEventListener('click', () => { ui.closeBriefing(); audio.ui(); });
$('btn-pause-settings').addEventListener('click', () => { ui.showSettings(); });
$('btn-resume').addEventListener('click', () => { audio.resume(); game.resume(); });
$('btn-restart').addEventListener('click', () => { audio.init(); audio.resume(); game.start(); });
$('btn-quit').addEventListener('click', () => { game.toMenu(); });
$('btn-retry').addEventListener('click', () => { audio.init(); audio.resume(); game.start(); });
$('btn-over-menu').addEventListener('click', () => { game.toMenu(); });

document.addEventListener('keydown', (e) => {
  if (e.code !== 'Escape') return;
  const settingsOpen = !$('screen-settings').classList.contains('hidden');
  const briefingOpen = !$('screen-briefing').classList.contains('hidden');
  if (settingsOpen) { ui.closeSettings(); return; }
  if (briefingOpen) { ui.closeBriefing(); return; }
});

// init audio after any first interaction so menu ambience can start
window.addEventListener('pointerdown', () => {
  if (!audio.ctx) {
    audio.init();
    audio.setEnabled(settings.sound);
  }
}, { once: true });

/* ------------------------------------------------------------------ */
/* Loop                                                                */
/* ------------------------------------------------------------------ */
const clock = new THREE.Clock();
let firstFrame = true;
let elapsed = 0;

function resize() {
  const w = window.innerWidth, h = window.innerHeight;
  camera.aspect = w / h;
  camera.updateProjectionMatrix();
  renderer.setSize(w, h);
  composer.setSize(w, h);
  bloom.resolution.set(w, h);
}
window.addEventListener('resize', resize);
window.addEventListener('orientationchange', () => setTimeout(resize, 120));

document.addEventListener('visibilitychange', () => {
  if (document.hidden && game.mode === 'playing') game.pause();
});

function animate() {
  requestAnimationFrame(animate);
  const dt = Math.min(clock.getDelta(), 0.05);
  elapsed += dt;
  game.update(dt);
  composer.render();
  if (firstFrame) {
    firstFrame = false;
    ui.loader(1);
    setTimeout(() => ui.hideLoader(), 550);
  }
}

ui.loader(1);
animate();

// debugging hook used by automated visual checks
window.__nightfall = { game, renderer, scene, camera, composer };

