const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
mkdirSync('screenshots', { recursive: true });

const browser = await chromium.launch({
  headless: true,
  executablePath: '/usr/bin/chromium',
  args: ['--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--ignore-gpu-blocklist', '--disable-gpu-sandbox'],
});
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const errors = [];
page.on('pageerror', e => { errors.push('PAGEERROR: ' + e.message); });
page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()); });
await page.goto('http://localhost:3002', { waitUntil: 'load' });
await page.waitForTimeout(2500);
await page.screenshot({ path: 'screenshots/menu.png' });
console.log('STATE1', JSON.stringify(await page.evaluate(() => {
  const g = window.__nightfall?.game;
  return { hasGame: !!g, mode: g?.mode };
})));

await page.click('#btn-deploy');
await page.waitForTimeout(1200);
// Simulate a few seconds of gameplay and stage hostiles for visual inspection.
console.log('STAGE', JSON.stringify(await page.evaluate(() => {
  const g = window.__nightfall.game;
  g.player.pos.set(0, 0, 31);
  g.player.yaw = 0;
  g.player.pitch = -0.01;
  g.wave = 3;
  g.waveState = { phase: 'active', toSpawn: 4, alive: 3, spawnTimer: 99, intermission: 0 };
  g.spawnEnemy();
  const es = g.enemies.slice(-1);
  es[0].position.set(-2.5, 0, 19);
  es[0].root.position.set(-2.5, 0, 19);
  g.spawnEnemy();
  const e2 = g.enemies.slice(-1)[0];
  e2.position.set(3.6, 0, 14); e2.root.position.set(3.6, 0, 14);
  g.spawnEnemy();
  const e3 = g.enemies.slice(-1)[0];
  e3.position.set(0.5, 0, 23); e3.root.position.set(0.5, 0, 23);
  for (let i = 0; i < 20; i++) g.update(0.05);
  return { mode: g.mode, enemies: g.enemies.length, health: g.player.health };
})));
await page.waitForTimeout(1600);
await page.screenshot({ path: 'screenshots/game.png' });

// ADS check
await page.evaluate(() => { const g = window.__nightfall.game; g.adsHeld = true; for (let i = 0; i < 24; i++) g.update(0.05); });
await page.waitForTimeout(700);
await page.screenshot({ path: 'screenshots/ads.png' });

// Fire check with muzzle flash mid-burst
