  const g = window.__nightfall.game;
  g.adsHeld = false;
  g.firing = true;
  for (let i = 0; i < 26; i++) g.update(0.05);
  g.firing = false;
  return { ammo: g.player.ammo, shots: g.shotsFired, hits: g.shotsHit, kills: g.kills, score: g.score, effects: g.effects.length };
});
console.log('FIRE', JSON.stringify(fireState));
await page.waitForTimeout(500);
await page.screenshot({ path: 'screenshots/fire.png' });

// Long autoplay sanity: simulate 60 seconds of gameplay quickly.
const sim = await page.evaluate(() => {
  const g = window.__nightfall.game;
  g.player.health = 100;
  g.waveState = { phase: 'active', toSpawn: 0, alive: g.waveState.alive, spawnTimer: 0, intermission: 0 };
  for (let i = 0; i < 400; i++) {
