await page.waitForTimeout(1500);
await page.click('#btn-deploy');
await page.waitForTimeout(1000);
const out = await page.evaluate(() => {
  const g = window.__nightfall.game;
  const THREE = window.__nightfall.scene.constructor; // not useful
  g.player.pos.set(0, 0, 31);
  g.player.yaw = 0; g.player.pitch = -0.04;
  g.waveState = { phase: 'active', toSpawn: 9, alive: 0, spawnTimer: 99, intermission: 0 };
  g.spawnEnemy();
  const e = g.enemies[g.enemies.length - 1];
  e.position.set(0, 0, 16); e.root.position.set(0, 0, 16);
  for (let i = 0; i < 10; i++) g.update(0.02);
  window.__nightfall.composer.render();
  const cam = g.camera;
  const camPos = cam.getWorldPosition(new (cam.position.constructor)());
  const dir = cam.getWorldDirection(new (cam.position.constructor)());
  const ray = g.raycaster;
  ray.set(camPos, dir); ray.far = 200;
  const targets = g.world.solidMeshes.slice();
  for (const en of g.enemies) if (en.alive) targets.push(...en.hitMeshes);
  const hits = ray.intersectObjects(targets, false);
  const allHits = hits.slice(0, 8).map(h => ({ d: +h.distance.toFixed(2), type: h.object.userData.enemy ? 'enemy' : 'world', mult: h.object.userData.hitMult, geo: h.object.geometry.type }));
  const eHits = ray.intersectObjects(e.hitMeshes, false).map(h => ({ d: +h.distance.toFixed(2), mult: h.object.userData.hitMult, geo: h.object.geometry.type, pos: h.point.toArray().map(v => +v.toFixed(2)) }));
  const ep = e.position.toArray();
  const before = { ammo: g.player.ammo, shots: g.shotsFired, hits: g.shotsHit };
  g.firing = true;
  for (let i = 0; i < 5; i++) { g.update(0.1); window.__nightfall.composer.render(); }
  g.firing = false;
  return {
    camPos: camPos.toArray().map(v => +v.toFixed(2)), dir: dir.toArray().map(v => +v.toFixed(3)),
    pitch: g.player.pitch, rigY: g.rig.position.y, enemyPos: ep, enemyAlive: e.alive,
    allHits, eHits, before, after: { ammo: g.player.ammo, shots: g.shotsFired, hits: g.shotsHit, health: e.health },
    enemiesLen: g.enemies.length, hitMeshesLen: e.hitMeshes.length,
  };
});
