import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true, executablePath: '/usr/bin/chromium', args: ['--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--ignore-gpu-blocklist'] });
const page = await browser.newPage({ viewport: { width: 1100, height: 700 } });
const errors = [];
page.on('pageerror', e => errors.push(e.message));
await page.goto('http://localhost:3002', { waitUntil: 'load' });
await page.waitForTimeout(1500);
await page.click('#btn-deploy');
await page.waitForTimeout(800);

const result = await page.evaluate(() => {
  const nf = window.__nightfall;
  const g = nf.game;
  const out = {};
  const run = (frames, dt = 0.05) => {
    for (let i = 0; i < frames; i++) {
      g.scene.updateMatrixWorld(true);
      g.update(dt);
    }
    g.scene.updateMatrixWorld(true);
  };

  // isolate a single target directly ahead
  g.waveState = { phase: 'active', toSpawn: 9, alive: 0, spawnTimer: 999, intermission: 0 };
  g.spawnEnemy();
  const e = g.enemies[g.enemies.length - 1];
  e.position.set(0, 0, 15);
  e.root.position.set(0, 0, 15);
  e.spawnDelay = 999;
  g.player.pos.set(0, 0, 31);
  g.player.yaw = 0;
  g.player.pitch = -0.055;
  run(2);
  out.targetHealth = e.health;
  out.ammo0 = g.player.ammo;
  g.firing = true;
  run(70);
  g.firing = false;
  out.afterFire = { ammo: g.player.ammo, reserve: g.player.reserve, kills: g.kills, score: g.score, shots: g.shotsFired, hits: g.shotsHit, alive: e.alive, health: e.health };
  out.reloading = g.player.reloading;

  // manual reload
  g.player.ammo = 4;
  g.player.reserve = 150;
  g.player.reloading = false;
  g.reload();
  run(44);
  out.reload = { ammo: g.player.ammo, reserve: g.player.reserve, reloading: g.player.reloading };

  // wave completion -> intermission -> next wave
  g.waveState = { phase: 'active', toSpawn: 0, alive: 0, spawnTimer: 0, intermission: 0 };
  const waveBefore = g.wave;
  run(2);
  out.intermission = { phase: g.waveState.phase, intermission: g.waveState.intermission > 0 };
  run(115);
  out.nextWave = { wave: g.wave, phase: g.waveState.phase, toSpawn: g.waveState.toSpawn, waveBefore };

  // grenade
  const grenadesBefore = g.grenadesLeft;
  g.throwGrenade();
  out.grenadeCount = { before: grenadesBefore, after: g.grenadesLeft, live: g.grenades.length };
  run(70);
  out.grenadeAfter = { live: g.grenades.length, effects: g.effects.length };

  // pause / resume state machine
  g.pause();
  out.paused = { mode: g.mode, screen: !document.getElementById('screen-pause').classList.contains('hidden') };
  g.resume();
  out.resumed = { mode: g.mode, screenHidden: document.getElementById('screen-pause').classList.contains('hidden') };

  // damage + game over
  g.damagePlayer(200, { x: 0, z: 10 });
  out.gameOver = { mode: g.mode, health: g.player.health, screen: !document.getElementById('screen-over').classList.contains('hidden') };

  // restart
  g.start();
  run(3);
  out.restart = { mode: g.mode, health: g.player.health, wave: g.wave, ammo: g.player.ammo, enemies: g.enemies.length, score: g.score };

  return out;
});
console.log(JSON.stringify(result, null, 2));
console.log('ERRORS', JSON.stringify(errors));
await browser.close();

